"""Delete only metadata reports generated by the Action, never a source checkout."""
import argparse
import os
from pathlib import Path
import stat


def cleanup(report,runner_temp):
    root=Path(runner_temp).resolve(strict=True)
    directory=Path(report).absolute().parent
    if (directory.parent.resolve()!=root or not directory.name.startswith('vulnforge-') or
        directory.is_symlink()): raise ValueError('Not an Action report directory')
    fd=os.open(directory,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW)
    try:
        files=os.listdir(fd)
        if set(files)-{'code.json','dependencies.json'}: raise ValueError('Unexpected directory contents')
        for name in files:
            info=os.stat(name,dir_fd=fd,follow_symlinks=False)
            if not stat.S_ISREG(info.st_mode) or info.st_uid!=os.getuid():
                raise ValueError('Unexpected report type')
        for name in files: os.unlink(name,dir_fd=fd)
    finally: os.close(fd)
    os.rmdir(directory)


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--report',required=True);parser.add_argument('--runner-temp',required=True)
    args=parser.parse_args()
    try: cleanup(args.report,args.runner_temp)
    except (OSError,ValueError): return 2
    return 0


if __name__=='__main__': raise SystemExit(main())
